package com.smarthub.plus;
import android.content.*;import android.graphics.Rect;import android.view.accessibility.AccessibilityNodeInfo;import java.util.*;
/** Receiver-sized bar, measured from the real INFO container when it is exposed. */
final class OsdGeometry {
 static int bar(int screen,float density,int receiverPermille,int manualPercent,boolean automatic){int fraction=automatic?(receiverPermille>0?receiverPermille:200):manualPercent*10;fraction=Math.max(160,Math.min(400,fraction));return Math.max(Math.round(96*density),Math.round(screen*fraction/1000f));}
 static int bar(Context c){SharedPreferences p=c.getSharedPreferences("smarthub",0);if(!p.getBoolean("osd_reference_compact_v1",false))p.edit().putBoolean("osd_reference_compact_v1",true).putBoolean("osd_receiver_size",false).putInt("osd_bar_percent",20).putLong("osd_changed_at",System.currentTimeMillis()).apply();return bar(c.getResources().getDisplayMetrics().heightPixels,c.getResources().getDisplayMetrics().density,p.getInt("native_osd_height_permille",0),p.getInt("osd_bar_percent",20),p.getBoolean("osd_receiver_size",false));}
 static int bottom(Context c){SharedPreferences p=c.getSharedPreferences("smarthub",0);int fraction=p.getInt("native_osd_bottom_permille",-1);return p.getBoolean("osd_receiver_size",false)&&fraction>=0?Math.round(c.getResources().getDisplayMetrics().heightPixels*Math.min(200,fraction)/1000f):0;}
 static int window(Context c){float d=c.getResources().getDisplayMetrics().density;int bottomBar=Math.max(bar(c),Math.round(TigerOsdMetrics.barHeightDp(true)*d));int posters=Math.round((135+30+17+(c.getSharedPreferences("smarthub",0).getBoolean("sports_ticker",false)?68:0))*d);return Math.min(c.getResources().getDisplayMetrics().heightPixels*4/5,bottomBar+posters);}
 static void observe(Context c,AccessibilityNodeInfo root){List<AccessibilityNodeInfo> names=root.findAccessibilityNodeInfosByViewId(SatelliteUiParser.DEFAULT_PACKAGE+":id/tv_channel_info_program_name"),events=root.findAccessibilityNodeInfosByViewId(SatelliteUiParser.DEFAULT_PACKAGE+":id/mtv_info_current_epg");Rect screen=new Rect(),event=new Rect();root.getBoundsInScreen(screen);for(AccessibilityNodeInfo e:events)try{if(e.isVisibleToUser())e.getBoundsInScreen(event);}finally{e.recycle();}if(screen.height()<1||event.isEmpty()){for(AccessibilityNodeInfo n:names)n.recycle();return;}Rect best=null;for(AccessibilityNodeInfo n:names){AccessibilityNodeInfo node=n;try{for(int depth=0;node!=null&&depth<12;depth++){Rect r=new Rect();node.getBoundsInScreen(r);if(r.contains(event)&&r.width()>=screen.width()*7/10&&r.height()>=screen.height()*16/100&&r.height()<=screen.height()*4/10&&r.bottom>=screen.height()*8/10&&(best==null||r.height()<best.height()))best=r;AccessibilityNodeInfo parent=node.getParent();if(node!=n)node.recycle();node=parent;}}finally{if(node!=null&&node!=n)node.recycle();n.recycle();}}if(best!=null){int fraction=best.height()*1000/screen.height(),bottom=Math.max(0,(screen.bottom-best.bottom)*1000/screen.height());SharedPreferences p=c.getSharedPreferences("smarthub",0);if(Math.abs(fraction-p.getInt("native_osd_height_permille",0))>2||Math.abs(bottom-p.getInt("native_osd_bottom_permille",-1))>2)p.edit().putInt("native_osd_height_permille",fraction).putInt("native_osd_bottom_permille",bottom).putLong("native_osd_measured_at",System.currentTimeMillis()).putLong("osd_changed_at",System.currentTimeMillis()).apply();}}
}
